def handle(name: rx.Var | str) -> rx.Component:
    """A named table that both the agent and the Python cells can refer to."""
    return rx.el.span(name, class_name="handle mono")


def zoom_button(pane: str) -> rx.Component:
    """Fill the window with this pane, or restore the layout. assets/panes.js clicks it on Shortcut.FULL_SCREEN."""
    return rx.el.button(
        rx.cond(State.zoomed == pane, ICON_COLLAPSE, ICON_EXPAND),
        title=rx.cond(
            State.zoomed == pane, Shortcut.FULL_SCREEN.hint("Restore panes"), Shortcut.FULL_SCREEN.hint("Full screen")
        ),
        on_click=State.toggle_zoom(pane),
        class_name=rx.cond(State.zoomed == pane, "zoom-btn mono is-on", "zoom-btn mono"),
    )


def logs_button(target: rx.Var | str, what: str) -> rx.Component:
    """The small bug button that opens the debug log on one thing's requests (State.show_logs),
    the reverse of a log row's ↖ link. Shown on hover of its row (.log-btn in app.css)."""
    return rx.el.button(
        ICON_BUG,
        title=f"Requests {what} made (debug log)",
        aria_label=f"Requests {what} made",
        on_click=State.show_logs(target).stop_propagation,
        class_name="log-btn mono",
    )


def chat_item(item: rx.Var) -> rx.Component:
    return rx.match(
        item.kind,
        # ids: what State.reveal scrolls to (the debug log's links, see ChatItem.key)
        (
            "user",
            rx.el.div(
                item.text,
                # top-right, on hover: this turn's requests, copy the message
                rx.el.div(
                    rx.cond(item.key != "", logs_button(item.key, "this turn")),
                    copy_button(item.text, "the message"),
                    class_name="bubble-actions",
                ),
                id=item.key,
                class_name="bubble is-user",
            ),
        ),
        (
            "step",
            rx.el.div(
                rx.el.span("▸", class_name="dim"),
                rx.el.span(item.name, class_name="tool-name"),
                rx.el.span(item.text, class_name="tool-args"),
                rx.cond(item.key != "", logs_button(item.key, "this tool call")),
                id=item.key,
                class_name="tool-step mono",
            ),
        ),
        ("ref", ref_item(item)),
        # what the turn cost, under its answer (session.TurnUsage.summary)
        (
            "usage",
            rx.el.div(
                rx.el.span(
                    item.text,
                    title="This turn: cost · input tokens (share read from the prompt cache) · output tokens",
                ),
                " · ",
                rx.el.button(
                    item.name,
                    title="Model requests this turn made: open the debug log (Requests)",
                    on_click=State.open_requests,
                    class_name="link-btn",
                ),
                class_name="turn-usage mono",
            ),
        ),
        # the app's own line, eg a slash command that was run (State.submit_chat)
        # a slash command that ran (State.submit_chat): a row as a tool call's, the command coloured
        # as in the chat box; a widget it added is the ref row after it
        (
            "slash",
            rx.el.div(
                rx.el.span("▸", class_name="dim"),
                rx.el.span(item.name, class_name="slash-token"),
                rx.el.span(item.text, class_name="tool-args"),
                title=item.text,
                class_name="tool-step mono",
            ),
        ),
        # the app's own line, eg a slash command that isn't one
        (
            "note",
            rx.el.div(
                rx.cond(item.name != "", rx.el.span(item.name, class_name="slash-token")),
                rx.el.span(item.text),
                class_name="chat-note mono",
            ),
        ),
        # the same traceback component as under a Python cell
        ("error", traceback_view(item.trace, item.trace_hidden, item.trace_more, item.text, "chat-trace")),
        markdown_bubble(text=item.text),
    )


@rx.memo
def markdown_bubble(text: rx.Var[str]) -> rx.Component:
    """An agent message. A memo component, so each bubble is its own React component: rx.markdown
    calls a hook (the color mode, for its component map), and inside the chat loop that hook ran
    once per message, so the number of hooks changed with every answer (React's hook-order warning)."""
    return rx.el.div(
        rx.markdown(text),
        # top-right, on hover: copy the reply as written (its markdown)
        rx.el.div(copy_button(text, "the reply"), class_name="bubble-actions"),
        class_name="bubble md",
    )


def ref_item(item: rx.Var) -> rx.Component:
    """A tool result: a row that folds its view open inline (collapsed by default), and opens it as a tab."""
    open_tab = State.select_object(item.name).stop_propagation
    return rx.el.div(
        rx.el.div(
            rx.el.span(rx.cond(item.open, "▾", "▸"), class_name="ref-caret dim"),
            handle(item.name),
            rx.el.span(item.text, class_name="dim"),
            rx.el.button("open →", title="Open as a tab in Results", on_click=open_tab, class_name="ref-open"),
            on_click=State.toggle_inline(item.name),
            title=rx.cond(item.open, "Hide the result", "Show the result here"),
            # what flashes when this row is revealed (rather than the whole unfolded view)
            custom_attrs={"data-flash": ""},
            class_name=rx.cond(item.open, "ref is-open", "ref"),
        ),
        # the same component as a tab shows, sized to its content (slot chat:<name>)
        rx.cond(
            item.open,
            rx.cond(
                item.view.kind != "",
                render_component(item.view, State.view_event, compact=True),
                rx.el.div("No longer available (the name was deleted or rebound).", class_name="ref-gone dim"),
            ),
        ),
        # the target of "Show in Chat" and debug-log links (State.reveal, assets/panes.js)
        id="ref-" + item.name.to(str),
        class_name="chat-ref",
    )


def agent_progress() -> rx.Component:
    """The one "agent is working" status, at the end of the chat: a pulsing 3x3 dot square, as in Zed's agent panel."""
    return rx.el.div(
        rx.el.span(*[rx.el.i() for _ in range(9)], class_name="dot-square"),
        rx.el.span(rx.cond(State.streaming == "", "Thinking…", "Generating…")),
        class_name="agent-progress",
    )


def context_meter() -> rx.Component:
    """How full the model's context window is and what the chat cost so far (State.context_label)."""
    return rx.cond(
        State.context_label != "",
        rx.el.div(
            rx.el.span(rx.el.i(style={"width": State.context_pct.to(str) + "%"}), class_name="ctx-bar"),
            rx.el.span(State.context_label),
            title=" ".join(
                [
                    "Conversation size (sent again with every request) / the model's context window,",
                    "and what the AI cost so far (chat and inline chats). Past about half, answers get slower and cost more.",
                ]
            ),
            class_name=rx.cond(State.context_pct >= 50, "ctx-meter mono is-full", "ctx-meter mono"),
        ),
    )


def slash_menu() -> rx.Component:
    """The slash commands (commands.SLASH), listed over the chat box while it holds "/" and the
    start of a name: type to filter, arrows move, Tab completes (with a space after, for one that
    takes text), Enter runs. All in the browser
    (assets/slash.js): picking one sends "/<name>" as the message, which State.submit_chat runs."""
    return rx.el.div(
        *[
            rx.el.button(
                rx.el.span(command.icon, class_name="palette-icon mono"),
                rx.el.span(
                    f"/{name}",
                    rx.el.span(" <text>", class_name="dim") if command.takes else "",
                    class_name="mono slash-name",
                ),
                rx.el.span(slash_about(command), class_name="dim palette-title"),
                rx.el.span(command.keys, class_name="palette-keys mono dim"),
                type="button",
                # data-takes: Tab completes with a space after, ready for the text (assets/slash.js)
                # data-about: the hover text of the command where it is typed
                custom_attrs={
                    "data-slash": name,
                    "data-words": command.words,
                    "data-takes": command.takes,
                    "data-about": slash_about(command),
                },
                class_name="menu-item palette-item",
            )
            for name, command in SLASH.items()
        ],
        rx.el.div("No such command", class_name="menu-empty dim"),
        custom_attrs={"data-slash-menu": ""},
        class_name="slash-menu sans",
    )


def chat_pane() -> rx.Component:
    return rx.el.div(
        rx.el.div(
            rx.el.span("Chat"),
            # the chat agent's model (agents.py; every agent's setup is in the debug panel's Agents tab)
            rx.el.span(AGENTS[0].model_name, title=f"Model: {AGENTS[0].model}", class_name="chat-model mono"),
            rx.el.span(class_name="spacer"),
            context_meter(),
            zoom_button("chat"),
            class_name="pane-title",
        ),
        rx.el.div(
            # column-reverse keeps the scroll pinned to the newest message
            rx.el.div(
                rx.el.div(
                    rx.cond(
                        State.chat.length() == 0,
                        rx.el.div(
                            "Ask about Smash Ultimate. What the agent pulls (tables, VODs, …) shows up below as r1, r2, … ",
                            "and is a plain Python object in the cells (tables are polars DataFrames).",
                            class_name="empty",
                        ),
                    ),
                    rx.foreach(State.chat, chat_item),
                    rx.cond(
                        State.busy & (State.streaming != ""),
                        markdown_bubble(text=State.streaming),
                    ),
                    rx.cond(State.busy, agent_progress()),
                    class_name="chat-items",
                ),
                class_name="chat-scroll",
            ),
            # shown once you scroll up (assets/panes.js adds .is-scrolled): back to the newest message
            rx.el.button(
                "↓",
                title="Jump to the newest message",
                aria_label="Jump to the newest message",
                type="button",
                custom_attrs={"data-chat-bottom": ""},
                class_name="chat-bottom",
            ),
            class_name="chat-body",
        ),
        rx.el.form(
            slash_menu(),
            # the box's text drawn again under it, to colour a slash command (assets/slash.js)
            rx.el.div(aria_hidden="true", custom_attrs={"data-slash-mirror": ""}, class_name="slash-mirror"),
            rx.el.textarea(
                name="prompt",
                placeholder=f"Ask the agent…  ({Shortcut.SEND.keys} to send, {Shortcut.NEW_LINE.keys} for a new line, / for commands)",
                enter_key_submit=True,
                # the cursor starts here when the app opens
                auto_focus=True,
                rows=2,
                class_name="input sans",
            ),
            on_submit=State.submit_chat,
            reset_on_submit=True,
            # while the agent works: the same sweep of light as the inline chat's (app.css)
            class_name=rx.cond(State.busy, "composer is-thinking", "composer"),
        ),
        class_name=rx.match(
            State.chat_layout,
            ("hidden", "chat-pane sans is-hidden"),
            ("alone", "chat-pane sans is-alone"),
            "chat-pane sans",
        ),
        custom_attrs={"data-pane": "chat"},
    )


def object_tab(obj: rx.Var) -> rx.Component:
    """A result tab: click selects, x closes, right-click opens the close menu (as in VS Code).
    Closing only hides the tab; the name stays in Python."""
    name = obj["name"]
    return rx.el.div(
        handle(name),
        rx.el.span(obj["shape"]),
        rx.el.span(obj["source"], class_name="dim"),
        rx.el.button(
            "×",
            title="Close (the name stays in Python)",
            on_click=State.close_tab(name).stop_propagation,
            class_name="tab-close",
        ),
        on_click=State.select_object(name),
        on_context_menu=lambda event: State.open_tab_menu(name, event).prevent_default,
        role="tab",
        id="tab-" + name.to(str),  # State.reveal('tab:<name>')
        class_name=rx.cond(State.selected == name, "tab is-active", "tab"),
    )


def menu_item(label: str, event: Any) -> rx.Component:
    """One row of a menu (assets/panes.js: arrows move between a menu's rows)."""
    return rx.el.button(label, on_click=event, class_name="menu-item")


def menu_search(placeholder: str) -> rx.Component:
    """A menu's search box, as in Omarchy's menus: it has the focus when the menu opens; typing
    filters the rows, arrows move, Enter picks. All in the browser (assets/panes.js,
    data-menu-search), so it is instant."""
    return rx.el.input(
        placeholder=placeholder,
        auto_focus=True,
        auto_complete="off",
        spell_check=False,
        custom_attrs={"data-menu-search": ""},
        class_name="menu-search",
    )


def palette_row(command: Command) -> rx.Component:
    """One command of the palette: icon, "Group: title", its shortcut. Running it closes the
    palette first; a `press` command is then run in the browser as its key (assets/panes.js)."""
    if command.event:
        name, *args = command.event
        run = getattr(State, name)(*args) if args else getattr(State, name)
    else:
        run = rx.call_script(f"window.smashPress({json.dumps(command.keys)})")
    title: Any = command.title
    if command.shown:
        title = rx.fragment(rx.cond(getattr(State, command.shown), "Hide ", "Show "), command.title)
    return rx.el.button(
        rx.el.span(command.icon, class_name="palette-icon mono"),
        rx.el.span(rx.el.span(command.group + ": ", class_name="dim"), title, class_name="palette-title"),
        rx.el.span(command.keys, class_name="palette-keys mono dim"),
        on_click=[State.close_palette, run],
        # data-command: what "recently used" remembers; data-words: found by these too (panes.js)
        custom_attrs={"data-command": command.id, "data-words": command.words},
        class_name="menu-item palette-item",
    )


def palette() -> rx.Component:
    """The command palette (Shortcut.PALETTE), as VS Code's and Omarchy's menu: a search box over
    every command (commands.py) and every open result ("Go to"). Typing filters, arrows move, Enter
    runs; the ones you ran last come first (assets/panes.js). Always on top, as Omarchy's launcher
    is: over the debug log, help, the keybindings list and a floating view, with its own backdrop,
    so closing it leaves what is under it open."""
    menu = rx.el.div(
        menu_search("Run a command…"),
        *[palette_row(command) for command in COMMANDS],
        rx.foreach(
            State.objects,
            lambda obj: rx.el.button(
                rx.el.span(ICON_RESULTS, class_name="palette-icon mono"),
                rx.el.span(rx.el.span("Go to: ", class_name="dim"), obj["name"], class_name="palette-title"),
                rx.el.span(obj["shape"], class_name="palette-keys dim"),
                on_click=[State.close_palette, State.select_object(obj["name"])],
                custom_attrs={"data-words": "result tab open switch"},
                class_name="menu-item palette-item",
            ),
        ),
        rx.el.div("No matching command", class_name="menu-empty dim"),
        custom_attrs={"data-palette": ""},
        class_name="menu sans is-centered is-palette",
    )
    backdrop = rx.el.div(on_click=State.close_palette, class_name="palette-backdrop")
    return rx.cond(State.palette, rx.fragment(backdrop, menu))


def overlays() -> rx.Component:
    """What floats over the page: a tab's right-click menu and the help panel. Clicking outside
    (or Esc, assets/panes.js) closes them."""
    return rx.cond(
        (State.menu_tab != "") | State.show_help | State.add_menu | State.show_debug,
        rx.fragment(
            rx.el.div(
                on_click=State.close_menus,
                on_context_menu=State.close_menus.prevent_default,
                class_name="overlay-backdrop",
            ),
            rx.cond(
                State.menu_tab != "",
                rx.el.div(
                    rx.cond(
                        State.chat_refs.contains(State.menu_tab),
                        rx.fragment(
                            menu_item("Show in Chat", State.show_in_chat(State.menu_tab)),
                            rx.el.div(class_name="menu-sep"),
                        ),
                    ),
                    menu_item("Show Requests", State.show_logs("tab:" + State.menu_tab)),
                    rx.el.div(class_name="menu-sep"),
                    menu_item("Close", State.close_tab(State.menu_tab)),
                    menu_item("Close Others", State.close_other_tabs(State.menu_tab)),
                    menu_item("Close to the Right", State.close_tabs_right(State.menu_tab)),
                    rx.el.div(class_name="menu-sep"),
                    menu_item("Close All", State.close_all_tabs),
                    style={"left": State.menu_x.to(str) + "px", "top": State.menu_y.to(str) + "px"},
                    class_name="menu sans",
                ),
            ),
            rx.cond(
                State.add_menu,
                rx.el.div(
                    rx.el.div("Add", class_name="menu-head"),
                    menu_search("Search widgets…"),
                    *[menu_item(widget.title, State.add_widget(widget.kind)) for widget in ADDABLE],
                    rx.el.div("No matching widget", class_name="menu-empty dim"),
                    # the "+" on the Results tab bar, at the pointer (the palette has these too)
                    style={"left": State.menu_x.to(str) + "px", "top": State.menu_y.to(str) + "px"},
                    class_name="menu sans",
                ),
            ),
            rx.cond(State.show_help, help_panel()),
            rx.cond(State.show_debug, debug_panel()),
        ),
    )


def debug_row(row: rx.Var) -> rx.Component:
    """One record: time, kind, summary; unfolds to its details (state.LogRow, logs.py)."""
    return rx.el.details(
        rx.el.summary(
            rx.el.span(row.time, class_name="dbg-time mono dim"),
            rx.el.span(row.kind, class_name="dbg-kind"),
            rx.el.span(row.summary, class_name="dbg-summary mono"),
            rx.foreach(row.badges, lambda badge: rx.el.span(badge, class_name="dbg-badge")),
            # where it came from: the tool call's chat row, the turn, the tab or the cell
            rx.cond(
                row.target != "",
                rx.el.button(
                    row.target_label,
                    title="Show where this came from",
                    # a click in <summary> would also fold the row open
                    on_click=State.reveal(row.target).stop_propagation.prevent_default,
                    class_name="dbg-link link-btn",
                ),
            ),
        ),
        rx.el.div(
            rx.el.div(
                rx.cond(row.curl != "", copy_button(row.curl, "the request as a curl command", "curl")),
                copy_button(row.copy, "this record as JSON", "JSON"),
                class_name="dbg-actions",
            ),
            rx.foreach(
                row.details,
                lambda detail: rx.cond(
                    detail["fold"] != "",
                    # long text you only sometimes want (a tool call's response): folded until clicked
                    rx.el.details(
                        rx.el.summary(detail["label"], class_name="dbg-label dim"),
                        rx.el.pre(detail["text"], class_name="dbg-text mono"),
                        class_name="dbg-fold",
                    ),
                    rx.el.div(
                        rx.el.div(detail["label"], class_name="dbg-label dim"),
                        rx.el.pre(detail["text"], class_name="dbg-text mono"),
                    ),
                ),
            ),
            class_name="dbg-details",
        ),
        class_name=rx.cond(row.error, "dbg-row is-error", "dbg-row"),
        key=row.id,
    )


